from pathlib import Path
import json,subprocess,statistics,hashlib,datetime
root=Path(Path('/tmp/photonic-location-root').read_text())
binary=Path('/Users/robertvanderzee/Library/Caches/bazel/_bazel_robertvanderzee/6259dc4c7713a84c173aa7f2cf7cf211/execroot/_main/bazel-out/darwin_arm64-opt/bin')
case=[('addition','expression',['2+2','11']),('product','expression',['2*2*2','22']),('compact','expression',['2*2*2*2*2*2','2101']),('decimal','arithmetic',['1234567890','add','9876543210','--radix','10']),('multiply','arithmetic',['12345','multiply','67890','--radix','10'])]
for name,argument in [('direct',['--depth','0','--width','8']),('partition',['--depth','1','--width','8']),('hierarchy',['--depth','2','--width','8']),('productive',['--depth','1','--width','8','--productive']),('changing',['--depth','1','--width','8','--alternating']),('scalar',['--depth','1','--width','8','--scalar'])]:
    case.append((name,'partition',argument))
artifact={'baseline':json.loads((root/'baseline.json').read_text())['revision'],'date':datetime.datetime.now().astimezone().isoformat(),'machine':subprocess.check_output(['sysctl','-n','machdep.cpu.brand_string'],text=True).strip(),'binary':{},'record':[],'summary':[],'exact':[],'allocation':[]}
for side,base in [('baseline',root/'baseline'),('candidate',binary/'benchmark')]:
    artifact['binary'][side]={target:hashlib.sha256((base/target).read_bytes()).hexdigest() for _,target,_ in case}
for iteration in range(3):
    for name,target,argument in case:
        for side in (['baseline','candidate'] if iteration%2==0 else ['candidate','baseline']):
            base=root/'baseline' if side=='baseline' else binary/'benchmark'
            result=json.loads(subprocess.check_output([str(base/target),*argument,'--sample','9'],text=True,timeout=180))
            artifact['record'].append({'round':iteration,'case':name,'side':side,'argument':argument+['--sample','9'],'result':result})
    (root/'audit.json').write_text(json.dumps(artifact,indent=2)+'\n')
    print('Timing round',iteration+1,'complete',flush=True)
for name,_,_ in case:
    sample={side:[m for r in artifact['record'] if r['case']==name and r['side']==side for m in r['result']['measurement']] for side in ['baseline','candidate']}
    expected={k:v for k,v in sample['baseline'][0].items() if k not in ['execution','initialization']}
    assert all({k:v for k,v in m.items() if k not in ['execution','initialization']}==expected for value in sample.values() for m in value),name
    value={side:statistics.median(m['execution'] for m in sample[side])*1000 for side in sample}
    tolerance=.1 if value['baseline']<1 else .05
    row={'case':name,**value,'unit':'millisecond','tolerance':tolerance,'passed':value['candidate']<=value['baseline']*(1+tolerance)}
    artifact['summary'].append(row);print(row,flush=True)
for side,base in [('baseline',root/'baseline'),('candidate',binary/'benchmark')]:
    result=json.loads(subprocess.check_output([str(base/'allocation'),'expression','2*2*2*2*2*2','2101','--sample','3'],text=True,timeout=180))
    artifact['allocation'].append({'side':side,'result':result})
(root/'audit.json').write_text(json.dumps(artifact,indent=2)+'\n')
print('Allocation complete',flush=True)
prior=Path(Path('/tmp/photonic-scope-location').read_text())
for name in ['exact','empty']:
    for case in json.loads((prior/(name+'.json')).read_text()):
        argument=case['argument']
        before=subprocess.check_output([str(root/'baseline/photonic'),*argument],timeout=180)
        after=subprocess.check_output([str(binary/'command/photonic'),*argument],timeout=180)
        assert before==after,case
        artifact['exact'].append({'case':case.get('case',case.get('source')),'argument':argument,'byte':len(before),'sha256':hashlib.sha256(before).hexdigest(),'equal':True})
    print(name,'reports equal',flush=True)
for index,case in enumerate(json.loads(Path('document/loading.json').read_text())['record']):
    argument=[str(root/f'loading-{index}.wave') if value=='<source>' else value for value in case['argument']]
    actual=json.loads(subprocess.check_output([str(binary/'command/photonic'),*argument],text=True))
    assert actual==case['report'],case['source']
artifact['loading']=11
artifact['source']={str(path):hashlib.sha256(path.read_bytes()).hexdigest() for path in [Path('language/joining.rs'),*sorted(Path('language/joining').glob('*.rs'))]}
artifact['script']=Path(__file__).read_text()
(root/'audit.json').write_text(json.dumps(artifact,indent=2)+'\n')
print(len(artifact['exact']),'reports byte-identical; 11 design probes equal.',flush=True)
